const matchPrice = (q,qty) => Math.round(Number(q.unit_price_paise||0)*qty);
const matchLanded = (q,qty) => matchPrice(q,qty)+Number(q.transport_paise||0)+Number(q.handling_paise||0);
const stageOrders=()=>safeList(state?.orders);
const stageLots=()=>safeList(state?.lots);
