function demoOtpFor(orderId){
 if(!orderId || !globalThis.crypto?.getRandomValues)return '';
 if(!stage1UI.demoOtpCodes[orderId]){
  const bytes=new Uint32Array(1);crypto.getRandomValues(bytes);
  stage1UI.demoOtpCodes[orderId]=String(100000+(bytes[0]%900000));
 }
 return stage1UI.demoOtpCodes[orderId];
}
