  {id:'SAMPLE-FPO-C',supplier_name:'Demo: Green Basket FPO',location:'Sample location C',crop:'Tomatoes',grade:'A',offered_kg:75,unit_price_paise:2300,transport_paise:30000,handling_paise:2500,status:'quoted',demo_km:12},
  {id:'SAMPLE-FPO-D',supplier_name:'Demo: Sunrise Cooperative',location:'Sample location D',crop:'Tomatoes',grade:'B',offered_kg:80,unit_price_paise:1650,transport_paise:57000,handling_paise:1800,status:'quoted',demo_km:33}
