function renderView(){const v={farmer:stageFarmer,fpo:stageFPO,marketplace:stageMarketplace,matching:stageMatching,payments:stagePayments,invoices:stageInvoices,logistics:stageLogistics,ratings:stageRatings,admin:stageAdmin,tracking:stageTracking};if(!isManager()){const allowed={portal:buyerPortal,marketplace:stageMarketplace,matching:stageMatching,tracking:stageTracking,payments:stagePayments,invoices:stageInvoices,ratings:stageRatings};return (allowed[view]||buyerPortal)();}return ({...v,overview,lots:lotsPage,orders:ordersPage,fulfillment:fulfillmentPage,recovery,economics:economicsPage,settlement,ledger:ledgerPage,activity})[view]?.() || overview();}
function login(){return `<div class="login-page"><section class="login-art"><div class="brand">${brand}</div><div><div class="eyebrow" style="color:#bed4ae">CROP RECOVERY & SETTLEMENT OS</div><h1>Good decisions.<br>Better harvests.</h1><p>Resolve original shortages, recover mismatched produce and reconcile farmer payments through one traceable case.</p></div><div class="text-xs" style="color:#aec6b3">TEAM INNOVATRIX · Hackathon prototype · No real payments</div></section><section class="login-form"><div class="brand">${brand}</div><span class="tagline">AGROVA V3 WORKSPACE</span><h2>Welcome back.</h2><p class="lead">Sign in to your manager or buyer workspace.</p><form data-form="login"><div class="field"><label>Email</label><input type="email" name="username" id="login-email" autocomplete="username" value="manager@agrova.test" required/></div><div class="field"><label>Password</label><input type="password" name="password" id="login-password" autocomplete="current-password" value="Agrova123!" required/></div>${loginError?`<div class="errorbox">${esc(loginError)}</div>`:''}<button type="submit" class="btn primary">Sign in →</button></form><div class="hint"><strong>Demo accounts (local only)</strong><br>FPO Manager: manager@agrova.test / Agrova123!<br>SauceWorks buyer: sauce@agrova.test / Buyer123!<br>FreshMart buyer: fresh@agrova.test / Buyer123!<div class="button-row"><button class="btn small" data-action="fill-login" data-login="manager">Use manager</button><button class="btn small" data-action="fill-login" data-login="buyer">Use buyer</button></div></div><p class="help">Demo credentials are not suitable for deployment to the public internet without changing the authentication setup.</p></section></div><div class="toasts" id="toasts"></div>`;}
function field(name,label,type='text',value='',attrs='') {return `<div class="field"><label for="f-${name}">${esc(label)}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`;}
function sel(name,label,options,chosen,attrs=''){return `<div class="field"><label for="f-${name}">${esc(label)}</label><select id="f-${name}" name="${name}" ${attrs}>${options.map(([value,title])=>`<option value="${esc(value)}" ${String(value)===String(chosen)?'selected':''}>${esc(title)}</option>`).join('')}</select></div>`;}
function modalHTML(){const {type,id}=modal;let title='',desc='',inner='';const gradeOptions=['A','B','C'].map(x=>[x,'Grade '+x]);const safetyOptions=[['cleared','Safety cleared'],['pending','Pending inspection'],['hold','Safety hold']];
 if(type==='passport'){const l=lotById(id);const orig=(state.original_allocations||[]).filter(a=>a.lot_id===id);const rec=state.offers.filter(o=>o.lot_id===id);const source=(state.suppliers||[]).find(q=>q.received_lot_id===id);title='Digital quality passport — '+l.id;desc='Internal FPO record, not government certification or independent testing.';inner=`<div class="passport"><div class="eyebrow">INTERNAL TRACEABILITY · ${esc(l.id)}</div><h3>${esc(l.crop)} · ${esc(l.farmer)}</h3><div class="kv"><span>Inspected quantity</span><strong>${kg(l.quantity_kg)} kg</strong></div><div class="kv"><span>Inspection grade</span>${chip('Grade '+l.grade)}</div><div class="kv"><span>Safety status</span>${chip(l.safety,l.safety==='cleared'?'':'warn')}</div><div class="kv"><span>Record revision</span><strong>${l.version}</strong></div><div class="kv"><span>Current uncommitted stock</span><strong>${kg(available(l))} kg</strong></div>${source?`<div class="note">Sourced from ${esc(source.supplier_name)} via ${esc(source.id)}. Source confirmation was simulated; receiving inspection entered by manager.</div>`:''}<h4>Linked recovery reservations</h4>${rec.map(o=>`<div class="help">${esc(o.id)} · ${kg(o.quantity_kg)} kg · ${esc(o.status)}</div>`).join('')||'<div class="help">None yet</div>'}<h4 style="margin-top:12px">Linked original buyer allocations</h4>${orig.map(a=>`<div class="help">${esc(a.id)} · ${kg(a.quantity_kg)} kg · ${esc(a.status)}</div>`).join('')||'<div class="help">None yet</div>'}<div class="note warning">This internal passport proves only what was entered and tracked by the prototype, not actual food safety compliance.</div></div><button class="btn primary" data-action="close">Close passport</button>`;}
 if(type==='source-quote'){title='Add partner sourcing quotation';desc='Manual quote, not a live supplier discovery API. A confirmation and physical inspection are required before inventory changes.';const originals=state.orders.filter(o=>o.is_original);const o=originals[0];inner=`<form data-form="source-create">${sel('original_order_id','Original buyer order',originals.map(x=>[x.id,x.buyer_name+' · Grade '+x.grade]),o?.id)}${field('supplier_name','Partner FPO or supplier','text','','required')}${field('location','Supply location','text','Delhi NCR','required')}${field('crop','Produce','text',o?.crop||'Tomatoes','required')}<div class="fields-grid">${sel('grade','Offered grade',gradeOptions,o?.grade||'A')}${field('offered_kg','Offered quantity (kg)','number',shortage(o)||25,'min="0.001" step="0.001" required')}${field('rate_inr','Source price (₹/kg)','number',21,'min="0" step="0.01" required')}${field('transport_inr','Transport estimate (₹)','number',50,'min="0" step="0.01" required')}${field('handling_inr','Handling estimate (₹)','number',10,'min="0" step="0.01" required')}</div><button class="btn primary">Save quote →</button></form>`;}
 if(type==='source-receive'){const q=state.suppliers.find(x=>x.id===id);title='Receive & inspect partner supply';desc=q.supplier_name+' · '+kg(q.offered_kg)+' kg confirmed in the demo. Receiving quality is independently verified by the manager.';inner=`<form data-form="source-receive" data-id="${id}">${field('received_kg','Actual received weight (kg)','number',q.offered_kg,`min="0.001" max="${q.offered_kg}" step="0.001" required`)}<div class="fields-grid">${sel('grade','Inspected grade',gradeOptions,q.grade)}${sel('safety','Safety inspection',safetyOptions,'cleared')}</div><div class="note warning">Received Grade A, safety-cleared tomatoes can help cover FreshMart. Wrong grade or safety hold creates a separate lot but does not resolve its shortage.</div><button class="btn primary">Record receiving inspection</button></form>`;}
 if(type==='lot'){title='Add farmer lot';desc='New data changes eligibility and dashboard totals immediately.';inner=`<form data-form="create-lot">${field('farmer','Farmer name','text','','required maxlength="140"')}${field('crop','Produce / crop','text','Tomatoes','required')}${field('quantity_kg','Received quantity (kg)','number','40','step="0.001" min="0.001" required')}<div class="fields-grid">${sel('grade','Inspection grade',gradeOptions,'B')}${sel('safety','Safety clearance',safetyOptions,'cleared')}</div><button class="btn primary" type="submit">Create lot</button></form>`;}
 if(type==='edit-lot'){const l=lotById(id);title=`Inspect ${l.id}`;desc=reservedForLot(l.id)?'Reserved/delivered lots are locked against silent changes to grade or safety.':'Update inspection and rerun eligibility.';inner=`<form data-form="edit-lot" data-id="${id}"><strong>${esc(l.farmer)} · ${esc(l.crop)}</strong>${field('quantity_kg','Total lot quantity (kg)','number',l.quantity_kg,`step="0.001" min="${Math.max(0.001,reservedForLot(l.id))}" required`)}<div class="fields-grid">${sel('grade','Grade',gradeOptions,l.grade)}${sel('safety','Safety status',safetyOptions,l.safety)}</div><div class="note">${kg(reservedForLot(l.id))} kg is reserved or already delivered. Cannot reduce the lot below this quantity.</div><button class="btn primary" type="submit">Save inspection revision</button></form>`;}
 if(type==='order'){title='Add buyer order';desc='A new alternative buyer is eligible only if requirements match an available, cleared lot.';inner=`<form data-form="create-order">${field('buyer_name','Buyer / company','text','New Processing Co','required')}${field('buyer_id','Buyer ID (lowercase, e.g. newprocessing)','text','newprocessing','required pattern="[a-z0-9_-]+"')}${field('crop','Crop','text','Tomatoes','required')}<div class="fields-grid">${sel('grade','Required grade',gradeOptions,'B')}${field('quantity_kg','Maximum demand (kg)','number','20','min="0.001" step="0.001" required')}${field('price_inr','Agreed rate (₹/kg)','number','18','min="0" step="0.01" required')}${sel('availability','Availability',[['accepting','Accepting offers'],['paused','Not accepting']],'accepting')}${field('transport_inr','Estimated transport cost (₹)','number',35,'min="0" step="0.01"')}${field('handling_inr','Estimated handling cost (₹)','number',5,'min="0" step="0.01"')}</div><div class="note">New buyer IDs have no login account by default. Manager may use clearly labelled demo acceptance, or use existing SauceWorks/FreshMart accounts.</div><button class="btn primary">Create buyer order</button></form>`;}
 if(type==='case'){title='Open recovery case';desc='Connect an inspected lot with an original buyer that cannot fully use it.';const original=state.orders.filter(o=>o.is_original);inner=`<form data-form="create-case">${sel('lot_id','Affected lot',state.lots.map(l=>[l.id,`${l.id} · ${l.farmer} · ${kg(l.quantity_kg)} kg Grade ${l.grade}`]),state.lots.find(l=>l.grade!=='A')?.id||state.lots[0]?.id)}${sel('original_order_id','Original order',original.map(o=>[o.id,`${o.id} · ${o.buyer_name} · Grade ${o.grade}`]),original[0]?.id)}<button class="btn primary">Create recovery case</button></form>`;}
 if(type==='offer'){const ctx=getContext();title='Send recovery offer';desc='Proposal only. Stock is not reserved until buyer acceptance and manager confirmation.';const eligibleOptions=state.orders.filter(o=>!o.is_original&&feasible(ctx.lot,o)>0);inner=eligibleOptions.length?`<form data-form="create-offer">${sel('order_id','Compatible buyer',eligibleOptions.map(o=>[o.id,`${o.buyer_name} · ${kg(feasible(ctx.lot,o))} kg max · ${rs(o.price_paise)}/kg`]),eligibleOptions[0].id)}${field('quantity_kg','Offer quantity (kg)','number',feasible(ctx.lot,eligibleOptions[0]),'min="0.001" step="0.001" required')}<div class="note">Buyer must accept. Manager must separately reserve stock. Backend checks latest availability atomically.</div><button class="btn primary">Send buyer offer →</button></form>`:'<div class="empty">No buyer is currently compatible. Change requirements or add a buyer order.</div>';}
 if(type==='delivery'){const o=offerById(id);title='Record delivery inspection';desc=`${o.id} · ${kg(o.quantity_kg)} kg reserved. The entire reservation is delivered in this prototype.`;inner=`<form data-form="create-delivery" data-id="${id}">${field('delivered_kg','Delivered quantity (kg)','number',o.quantity_kg,'step="0.001" min="0.001" readonly required')}<div class="fields-grid">${field('accepted_kg','Accepted (kg)','number',Math.max(0,o.quantity_kg-2),'step="0.001" min="0" required')}${field('rejected_kg','Rejected (kg)','number',Math.min(2,o.quantity_kg),'step="0.001" min="0" required')}</div><div class="field"><label>Inspection note</label><textarea name="inspection_note" placeholder="Condition, grade, custody of rejected portion, etc.">Provisional inspection; rejected goods held for reinspection.</textarea></div><div class="note">Accepted + rejected must equal delivered. Rejected produce is not automatically made available for resale.</div><button class="btn primary">Record inspection →</button></form>`;}
 if(type==='upload'){title='Upload evidence';desc='Attach a delivery receipt or buyer statement to this delivery. Files are kept private on the server.';inner=`<form data-form="upload" data-id="${id}">${sel('kind','Document type',[['inspection','Delivery inspection receipt'],['buyer','Buyer settlement statement']],'buyer')}<div class="field"><label for="upload-file">Choose file (up to 5 MB)</label><input type="file" id="upload-file" name="file" accept=".txt,.pdf,.png,.jpg,.jpeg,.webp,text/plain,application/pdf,image/*" required></div><div class="note">${state.ai_enabled?'Gemini enabled. After uploading, run extraction, then verify each field.':'Gemini key is not configured. TXT files have honest offline text parsing; PDF/images can be manually verified.'}</div><button class="btn primary">Upload document</button></form>`;}
 if(type==='verify'){const doc=state.deliveries.flatMap(d=>d.evidence).find(d=>d.id===id);const proposed=doc.verified||doc.proposed||{};const d=state.deliveries.find(d=>d.id===doc.delivery_id);title='Verify extracted fields';desc=`${doc.id} · ${doc.file_name} · ${doc.kind==='inspection'?'Inspection':'Buyer statement'} source. Compare every value with the real document before confirming.`;inner=`<form data-form="verify" data-id="${id}"><div class="note ${doc.proposed?'':'warning'}">${doc.proposed?`Suggested extraction: ${esc(doc.engine)}. Manager confirmation is required.`:'No extraction available. Manually enter the actual document values; do not guess.'}</div><div class="fields-grid">${field('accepted_kg','Accepted quantity (kg) *','number',proposed.accepted_kg??'','step="0.001" min="0" required')}${field('rejected_kg','Rejected quantity (kg)','number',proposed.rejected_kg??'','step="0.001" min="0"')}${field('delivered_kg','Delivered quantity (kg)','number',proposed.delivered_kg??'','step="0.001" min="0"')}${field('rate_inr','Document rate (₹/kg)','number',proposed.rate_inr??'','step="0.01" min="0"')}${field('deductions_inr','Document deductions (₹)','number',proposed.deductions_inr??0,'step="0.01" min="0"')}${field('lot_ref','Lot reference','text',proposed.lot_ref??'')}</div>${field('source_reference','Source line / page / explanation','text',proposed.source_reference??'','maxlength="220"')}<p class="help">Delivery recorded ${kg(d.delivered_kg)} kg. Accepted quantity cannot exceed delivered quantity. Agreed rate comes from the accepted offer, not AI.</p><button class="btn primary">Confirm verified fields</button></form>`;}
 if(type==='correct'){const doc=state.deliveries.flatMap(d=>d.evidence).find(d=>d.id===id);const current=doc.verified||{};title='Correct verified evidence';desc=`${doc.id} · ${doc.file_name} · ${doc.kind==='inspection'?'Inspection receipt':'Buyer statement'}. Corrections are separate, deliberate, and audit logged.`;inner=`<form data-form="correction" data-id="${id}"><div class="note warning">This changes values already used by reconciliation. Review the source document and explain the correction.</div><div class="fields-grid">${field('accepted_kg','Accepted quantity (kg) *','number',current.accepted_kg??'','step="0.001" min="0" required')}${field('rejected_kg','Rejected quantity (kg)','number',current.rejected_kg??'','step="0.001" min="0"')}${field('delivered_kg','Delivered quantity (kg)','number',current.delivered_kg??'','step="0.001" min="0"')}${field('rate_inr','Document rate (₹/kg)','number',current.rate_inr??'','step="0.01" min="0"')}${field('deductions_inr','Document deductions (₹)','number',current.deductions_inr??0,'step="0.01" min="0"')}${field('lot_ref','Lot reference','text',current.lot_ref??'')}</div>${field('source_reference','Source line / page / explanation','text',current.source_reference??'','maxlength="220"')}<div class="field"><label>Correction reason *</label><textarea name="reason" required minlength="10" maxlength="1000" placeholder="Explain why the verified evidence must change."></textarea></div><button class="btn primary" disabled>Save correction</button></form>`;}
 if(type==='review'){const d=state.deliveries.find(d=>d.id===id);title='Record human decision';desc='Document discrepancies are evidence for review, not an automatic fraud or payment decision.';inner=`<form data-form="review" data-id="${id}">${sel('decision','Reviewer action',[['more_evidence','Request more evidence'],['inspection_basis','Accept inspection basis'],['buyer_basis','Accept buyer statement basis']],'more_evidence')}<div class="field"><label>Required justification</label><textarea name="note" required minlength="10" placeholder="What did you verify? Which document supports the decision?"></textarea></div><div class="note warning">No transfer is sent. Reviewed settlements remain UNPAID. All decisions are audit logged.</div><button class="btn primary">Record decision</button></form>`;}
 return `<div class="modal-backdrop" data-action="close-outside"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="rowbetween" style="margin-bottom:16px"><div><h2>${esc(title)}</h2></div><button class="modal-close" aria-label="Close" data-action="close">×</button></div><p class="modal-desc">${esc(desc)}</p>${inner}</div></div>`;}
function render(){const root=$('#app');root.innerHTML=state?chrome():login();renderToast();}
async function work(fn,success){if(loading)return;loading=true;document.body.classList.add('is-working');
 try{await fn();modal=null;const ok=await refresh();if(success&&ok)notify(success);else if(!ok)notify('Operation submitted, but the latest server state could not be loaded. Check the server before retrying.',true);}
 catch(e){notify(e.message||'Operation failed',true);}
 finally{loading=false;document.body.classList.remove('is-working');}
}
function dataFrom(form){return Object.fromEntries(new FormData(form).entries());}
document.addEventListener('click',async e=>{
 const btn=e.target.closest('[data-action]');if(!btn)return;const action=btn.dataset.action,id=btn.dataset.id;
 if(action==='stage-search'){
  stage1UI.buyerSearch=$('#stage-market-search')?.value||'';stage1UI.buyerGrade=$('#stage-market-grade')?.value||'all';render();return;
 }
 if(action==='stage-choose-order'){
  stage1UI.matchOrderId=id;stage1UI.buyerQuantity=Math.min(Number(stageOrders().find(o=>o.id===id)?.quantity_kg||25),25);view='matching';render();window.scrollTo(0,0);return;
 }
 if(action==='stage-recalculate'){
  const n=Number($('#stage-quantity')?.value);const max=Number(stageOrders().find(o=>o.id===(stage1UI.matchOrderId||stageOrders()[0]?.id))?.quantity_kg||0);
  if(!Number.isFinite(n)||n<=0||n>max){notify('Quantity must be greater than 0 and no more than buyer demand.',true);return;}
  stage1UI.buyerQuantity=n;
  document.querySelectorAll('[data-distance-id]').forEach(el=>{const val=el.value.trim();if(val==='')delete stage1UI.distances[el.dataset.distanceId];else{const x=Number(val);if(Number.isFinite(x)&&x>=0&&x<=20000)stage1UI.distances[el.dataset.distanceId]=x;}});
  render();notify('Estimates recalculated. Distance data remains user-entered demo values.');return;
 }
 if(action==='stage-payment'){
  const valid=['pending','success','failed','delayed','refund'];if(!valid.includes(btn.dataset.status))return;
  const order=stageOrder();if(!order){notify('Choose an order first.',true);return;}
  const key=crypto.randomUUID().replaceAll('-','');
  return work(()=>request('/payments/demo-attempts','POST',{order_id:order.id,status:btn.dataset.status,idempotency_key:key}),`Simulated ${btn.dataset.status} recorded for ${order.id}. No real payment made.`);
 }
 if(action==='stage-invoice'){stage1UI.invoiceOrderId=id;render();return;}
 if(action==='stage-print'){
  const section=document.querySelector('#stage-print-invoice');if(!section){notify('Choose an order for invoice preview.',true);return;}
  window.print();return;
 }
 if(action==='close-outside'){if(e.target===btn){modal=null;render();}return;}
 if(action==='close'){modal=null;render();return;}
 if(action==='view'){view=btn.dataset.view;modal=null;render();window.scrollTo(0,0);return;}
 if(action==='open'){modal={type:btn.dataset.modal,id};render();return;}
 if(action==='verify-evidence'||action==='correct-evidence'){
  if(!isManager()){notify('FPO manager access required.',true);return;}
  modal={type:action==='correct-evidence'?'correct':'verify',id};render();return;
 }
 if(action==='fill-login'){$('#login-email').value=btn.dataset.login==='buyer'?'sauce@agrova.test':'manager@agrova.test';$('#login-password').value=btn.dataset.login==='buyer'?'Buyer123!':'Agrova123!';return;}
 if(action==='logout'){try{await request('/auth/logout','POST');state=null;view='overview';loginError='';stage1UI.demoOtpCodes={};stage1UI.demoDeliveryByOrder={};render();notify('Signed out.');}catch(err){notify(err.message||'Sign out failed.',true);}return;}
 if(action==='reset'){if(!confirm('Reset all demo lots, offers, deliveries, evidence references and audit events? This cannot be undone.'))return;await work(()=>request('/demo/reset','POST'),'Demo data reset.');view='overview';return;}
 if(action==='speak'){const text=$('#hindi-explanation')?.textContent;if(text&&'speechSynthesis' in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='hi-IN';u.rate=.9;speechSynthesis.speak(u);}else notify('Hindi text-to-speech is not supported in this browser.',true);return;}
 if(action==='demo-accept')return work(()=>request(`/offers/${id}/demo-accept`,'POST'),'Simulated buyer acceptance recorded.');
 if(action==='buyer-accept')return work(()=>request(`/offers/${id}/accept`,'POST'),'Offer accepted as buyer.');
 if(action==='reserve')return work(()=>request(`/offers/${id}/reserve`,'POST'),'Reserved with an atomic inventory check.');
 if(action==='cancel'){if(confirm('Cancel this offer and release any reservation?'))return work(()=>request(`/offers/${id}/cancel`,'POST'),'Offer cancelled.');return;}
 if(action==='source-confirm'){if(!confirm('Demo only: mark partner quotation as confirmed? No real supplier is contacted.'))return;return work(()=>request(`/sourcing/${id}/confirm`,'POST',{}),'Illustrative supplier confirmation recorded. Receive and inspect next.');}
 if(action==='source-cancel')return work(()=>request(`/sourcing/${id}/cancel`,'POST',{}),'Supplier quote cancelled.');
 if(action==='auto-allocate')return work(()=>request('/original/auto-allocate','POST',{order_id:id}),'Eligible stock reserved for original order. Dispatch/acceptance still pending.');
 if(action==='original-dispatch')return work(()=>request(`/original/allocations/${id}/dispatch`,'POST',{}),'Original stock marked dispatched; not yet buyer accepted.');
 if(action==='original-cancel')return work(()=>request(`/original/allocations/${id}/cancel`,'POST',{}),'Original allocation released.');
 if(action==='extract')return work(()=>request(`/evidence/${id}/extract`,'POST'),'Fields proposed. Open Verify fields to confirm against the document.');
});
document.addEventListener('change',e=>{if(e.target.matches('[data-farmer-price]')){const x=e.target.value,n=Number(x),lot=e.target.dataset.farmerPrice;if(x!==''&&(!Number.isFinite(n)||n<0||n>100000)){notify('Enter an expected price between 0 and ₹100,000.',true);return;}work(()=>request(`/lots/${encodeURIComponent(lot)}/expected-price`,'PUT',{price_inr:x===''?null:n}),'Expected farmer price saved.');return;}if(e.target.dataset.stageSelect){const key=e.target.dataset.stageSelect;if(['orderId','matchOrderId','deliveryOrderId'].includes(key)){stage1UI[key]=e.target.value;if(key==='matchOrderId'){const order=stageOrders().find(o=>o.id===e.target.value);stage1UI.buyerQuantity=Math.min(Number(order?.quantity_kg||25),25);}render();}return;} if(e.target.id==='case-switch'){selectedCaseId=e.target.value;render();}if(e.target.id==='economics-lot'){comparisonLotId=e.target.value;render();}});
document.addEventListener('submit',async e=>{
 const f=e.target.closest('form[data-form]');if(!f)return;e.preventDefault();const type=f.dataset.form,vals=dataFrom(f),id=f.dataset.id;
 const fNumber=['quantity_kg','price_inr','transport_inr','handling_inr','offered_kg','received_kg','delivered_kg','accepted_kg','rejected_kg','rate_inr','deductions_inr'];for(const key of fNumber)if(key in vals)vals[key]=vals[key]===''?null:Number(vals[key]);
 if(type==='login'){
  const submitButton=f.querySelector('button[type=submit],button:not([type])');
  try{
    if(submitButton)submitButton.disabled=true;
    await request('/auth/login','POST',vals);
    loginError='';stage1UI.demoOtpCodes={};stage1UI.demoDeliveryByOrder={};await refresh();
  }catch(e){
    loginError=e.message||'Login failed. Try again.';
    let hint=f.querySelector('[data-login-error]');
    if(!hint){hint=document.createElement('div');hint.dataset.loginError='true';hint.className='errorbox';hint.setAttribute('role','alert');f.append(hint);}
    hint.textContent=loginError;
  }finally{if(submitButton&&submitButton.isConnected)submitButton.disabled=false;}
  return;
 }
 if(type==='stage-order-request'){
  const crop=String(vals.crop||'').trim(),grade=String(vals.grade||'');const quantity=Number(vals.quantity),price=Number(vals.price);
  if(crop.length<2||crop.length>100||!['A','B','C'].includes(grade)||!Number.isFinite(quantity)||quantity<0.001||quantity>100000||!Number.isFinite(price)||price<=0||price>100000){notify('Enter a valid crop, grade, quantity and price.',true);return;}
  return work(()=>request('/buyer/orders','POST',{crop,grade,quantity_kg:quantity,price_inr:price}),'Buyer order request saved on the server; no payment or stock reservation.');
 }
 if(type==='stage-delivery'){
  const image=f.querySelector('input[name=proofFile]')?.files?.[0];
  const otp=String(vals.buyerOtp||'').trim();
  if(!image){notify('Delivery photo is mandatory for the demo.',true);return;}
  if(!['image/png','image/jpeg','image/webp'].includes(image.type)||image.size>5*1024*1024){notify('Use PNG, JPG or WEBP photo up to 5MB.',true);return;}
  const orderId=stageOrders().find(o=>o.id===stage1UI.deliveryOrderId)?.id||stageOrders()[0]?.id;
  if(!orderId){notify('Choose a delivery order.',true);return;}
  if(!/^\d{6}$/.test(otp)||otp!==demoOtpFor(orderId)){notify('Invalid browser-only test OTP for this order.',true);return;}
  stage1UI.demoDeliveryByOrder[orderId]={fileName:image.name,checkedAt:Date.now()};
  render();notify(`Demo input checks passed for ${orderId}. Delivery remains UNVERIFIED by the server.`);return;
 }
 if(type==='source-create')return work(()=>request('/sourcing/quotes','POST',vals),'Partner quote recorded. No stock added until inspection.');
 if(type==='source-receive')return work(()=>request(`/sourcing/${id}/receive`,'POST',vals),'Received supply added as inspected lot; original coverage recalculated.');
 if(type==='create-lot')return work(()=>request('/lots','POST',vals),'Lot created. Eligibility updated.');
 if(type==='edit-lot')return work(()=>request(`/lots/${id}`,'PATCH',vals),'Inspection revision saved.');
 if(type==='create-order')return work(()=>request('/orders','POST',vals),'Buyer order added.');
 if(type==='edit-order')return work(()=>request(`/orders/${id}`,'PATCH',vals),'Buyer matching recomputed.');
 if(type==='create-case')return work(async()=>{const result=await request('/cases','POST',vals);selectedCaseId=result.id;view='recovery';},'Recovery case created.');
 if(type==='create-offer')return work(()=>request('/offers','POST',{...vals,case_id:caseInfo().id}),'Buyer offer sent; not yet reserved.');
 if(type==='create-delivery')return work(async()=>{const result=await request('/deliveries','POST',{...vals,offer_id:id});window.__deliveryChoice=result.id;view='settlement';},'Inspection recorded. Attach evidence next.');
 if(type==='upload')return work(async()=>{const file=f.querySelector('input[type=file]').files[0];if(!file)throw Error('Choose a file.');if(file.size>5*1024*1024)throw Error('Maximum evidence file size is 5 MB.');let mime=file.type||({'txt':'text/plain','pdf':'application/pdf','png':'image/png','jpg':'image/jpeg','jpeg':'image/jpeg','webp':'image/webp'}[file.name.split('.').pop().toLowerCase()]);if(!mime)throw Error('Unsupported file. Use TXT, PDF or image.');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));await request('/evidence','POST',{delivery_id:id,kind:vals.kind,file_name:file.name,mime,base64:btoa(binary)});},'Evidence uploaded. Extract and confirm its fields.');
 if(type==='verify')return work(()=>request(`/evidence/${id}/verify`,'POST',vals),'Verified data saved; reconciliation recalculated.');
 if(type==='review')return work(()=>request('/reviews','POST',{...vals,delivery_id:id}),'Human decision recorded; payment remains unpaid.');
});
